<?php
if(!defined('SCHOOLOS_EXPERIENCE')){http_response_code(404);exit;}
function px_contacts(array $u):array{$tid=(int)$u['tenant_id'];$all=q('SELECT id,tenant_id,name,role FROM users WHERE tenant_id=? AND active=1 AND id<>? ORDER BY name LIMIT 2000',[$tid,$u['id']])->fetchAll();$out=[];foreach($all as $v)if(px_contact_allowed($u,$v))$out[]=$v;return $out;}
function px_contact_allowed(array $u,array $v):bool{if((int)$u['id']===(int)$v['id']||(int)$u['tenant_id']!==(int)($v['tenant_id']??0))return false;$tid=(int)$u['tenant_id'];$a=$u['role'];$b=$v['role'];if($a==='school_admin'||$b==='school_admin')return true;$adults=['teacher','staff','admissions'];if(in_array($a,$adults,true)&&in_array($b,$adults,true))return true;$parent=$a==='parent'?$u:($b==='parent'?$v:null);$student=$a==='student'?$u:($b==='student'?$v:null);$teacher=$a==='teacher'?$u:($b==='teacher'?$v:null);if($parent&&$student)return (bool)g("SELECT l.student_id FROM ecosystem_links l JOIN ecosystem_links s ON s.tenant_id=l.tenant_id AND s.student_id=l.student_id AND s.relation_type='student' WHERE l.tenant_id=? AND l.user_id=? AND s.user_id=? AND l.relation_type='parent' LIMIT 1",[$tid,$parent['id'],$student['id']]);if($teacher&&($parent||$student)){if(!xp_has('ac_allocations'))return false;$person=$parent??$student;$relation=$parent?'parent':'student';return (bool)g('SELECT l.student_id FROM ecosystem_links l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id JOIN ac_allocations a ON a.tenant_id=s.tenant_id AND a.class_id=s.class_id AND a.session_name=c.session_name WHERE l.tenant_id=? AND l.user_id=? AND l.relation_type=? AND a.teacher_id=? LIMIT 1',[$tid,$person['id'],$relation,$teacher['id']]);}return false;}
function px_recipients(array $u,mixed $raw):array{if(!is_array($raw))$raw=[$raw];if(count($raw)<1||count($raw)>30)throw new RuntimeException('Choose between 1 and 30 recipients.');$ids=[];$allowed=array_column(px_contacts($u),null,'id');foreach($raw as $id){if(!is_scalar($id)||!ctype_digit((string)$id)||!isset($allowed[(int)$id]))throw new RuntimeException('A recipient is outside your current school relationships.');$ids[(int)$id]=$allowed[(int)$id];}return $ids;}
function px_thread(array $u,int $id):array{$r=q('SELECT t.* FROM px_threads t JOIN px_members m ON m.thread_id=t.id AND m.tenant_id=t.tenant_id WHERE t.tenant_id=? AND t.id=? AND m.user_id=?',[$u['tenant_id'],$id,$u['id']])->fetch();if(!$r)throw new RuntimeException('Conversation unavailable.');$members=q('SELECT u.* FROM px_members m JOIN users u ON u.id=m.user_id AND u.tenant_id=m.tenant_id AND u.active=1 WHERE m.tenant_id=? AND m.thread_id=?',[$u['tenant_id'],$id])->fetchAll();foreach($members as $v)if((int)$v['id']!==(int)$u['id']&&!px_contact_allowed($u,$v))throw new RuntimeException('Conversation relationships have changed. Ask your school administrator.');return $r;}
function px_chat_start(array $u):int{global $pdo;$recipients=px_recipients($u,$_POST['recipients']??[]);$title=xp_text('title',180);$body=xp_text('body',4000);$members=[$u['id']=>$u]+$recipients;foreach($members as $x)foreach($members as $y)if($x['id']!==$y['id']&&!px_contact_allowed($x,$y))throw new RuntimeException('These recipients cannot share a group. Send separate private conversations to protect learner and family privacy.');return xp_tx(function()use($u,$recipients,$title,$body,$pdo){q('INSERT INTO px_threads(tenant_id,created_by,title) VALUES(?,?,?)',[$u['tenant_id'],$u['id'],$title]);$id=(int)$pdo->lastInsertId();foreach(array_merge([$u['id']],array_keys($recipients)) as $uid)q('INSERT INTO px_members(tenant_id,thread_id,user_id) VALUES(?,?,?)',[$u['tenant_id'],$id,$uid]);q('INSERT INTO px_messages(tenant_id,thread_id,user_id,body,client_key) VALUES(?,?,?,?,?)',[$u['tenant_id'],$id,$u['id'],$body,bin2hex(random_bytes(16))]);audit('chat.created','thread',(string)$id);return $id;});}
function px_chat_send(array $u,int $id,string $body,string $key):int{if(mb_strlen(trim($body))<1||mb_strlen($body)>4000||!preg_match('/^[a-f0-9]{32}$/D',$key))throw new RuntimeException('Enter a message of 1–4000 characters.');xp_rate('chat-send-'.$u['id'],30,1);return xp_tx(function()use($u,$id,$body,$key){global $pdo;q('SELECT id FROM px_threads WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$id]);px_thread($u,$id);q('INSERT INTO px_messages(tenant_id,thread_id,user_id,body,client_key) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)',[$u['tenant_id'],$id,$u['id'],trim($body),$key]);$sent=(int)$pdo->lastInsertId();$row=q('SELECT thread_id,body FROM px_messages WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$sent])->fetch();if(!$row||(int)$row['thread_id']!==$id||$row['body']!==trim($body))throw new RuntimeException('This message key was already used for different content. Refresh the conversation before sending a new message.');return $sent;});}
function px_chat_fetch(array $u,int $id,int $after):array{px_thread($u,$id);$rows=q('SELECT m.id,m.user_id,m.body,m.created_at,u.name FROM px_messages m JOIN users u ON u.id=m.user_id AND u.tenant_id=m.tenant_id WHERE m.tenant_id=? AND m.thread_id=? AND m.id>? ORDER BY m.id LIMIT 100',[$u['tenant_id'],$id,max(0,$after)])->fetchAll();if($rows)q('UPDATE px_members SET last_read=GREATEST(last_read,?) WHERE tenant_id=? AND thread_id=? AND user_id=?',[(int)end($rows)['id'],$u['tenant_id'],$id,$u['id']]);return $rows;}
function px_chat_view(array $u):void{echo '<section class="px-chat-hero"><span class="px-kicker">SCHOOL CONVERSATIONS</span><h2>Closer, in real time.</h2><p>Private conversations with your verified school connections. Messages refresh automatically while this page is open.</p></section>';if(!px_ready()){echo '<p>Your administrator can activate Portal Experience in Setup & Accounts.</p>';return;}$id=(int)($_GET['thread']??0);if($id)px_thread($u,$id);echo '<div class="px-chat-layout"><aside class="px-thread-list"><h3>Your conversations</h3>';foreach(q('SELECT t.*,MAX(msg.id) latest FROM px_threads t JOIN px_members m ON m.tenant_id=t.tenant_id AND m.thread_id=t.id LEFT JOIN px_messages msg ON msg.tenant_id=t.tenant_id AND msg.thread_id=t.id WHERE t.tenant_id=? AND m.user_id=? GROUP BY t.id,t.tenant_id,t.created_by,t.title,t.created_at ORDER BY latest DESC LIMIT 50',[$u['tenant_id'],$u['id']]) as $t){try{px_thread($u,(int)$t['id']);}catch(Throwable){continue;}echo '<a '.($id===(int)$t['id']?'aria-current="page"':'').' href="?s=chat&amp;thread='.(int)$t['id'].'">'.e($t['title']).'</a>';}echo '<details><summary>Start a conversation</summary><form method="post" class="px-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="px_action" value="chat_start"><label>Recipients (select one or more)<select name="recipients[]" multiple required size="6">';foreach(px_contacts($u) as $r)echo '<option value="'.(int)$r['id'].'">'.e($r['name'].' · '.$r['role']).'</option>';echo '</select></label><label>Subject<input name="title" maxlength="180" required></label><label>Your message<textarea name="body" maxlength="4000" required></textarea></label><p class="muted">Only verified relationships are listed. Group members must be permitted to communicate with each other.</p><button class="btn">Start conversation</button></form></details></aside><section class="px-chat-window">';if($id){echo '<div class="px-chat-status" role="status" id="pxChatStatus">Connecting…</div><div id="pxMessages" role="log" aria-live="polite" aria-relevant="additions" data-thread="'.$id.'"></div><form id="pxChatSend"><label for="pxChatBody">Message</label><textarea id="pxChatBody" maxlength="4000" required placeholder="Write a thoughtful message…"></textarea><button class="btn">Send message</button></form>';}else echo '<div class="px-empty"><span>✉</span><h3>Choose a conversation.</h3><p>Or start one with your school administrator, assigned teacher or verified family member.</p></div>';echo '</section></div>';}
function px_alerts(array $u):array{$out=[];$tid=(int)($u['tenant_id']??0);if(!$tid)return $out;if(px_ready()){$count=(int)g('SELECT COUNT(*) FROM px_messages msg JOIN px_members m ON m.thread_id=msg.thread_id AND m.tenant_id=msg.tenant_id WHERE m.tenant_id=? AND m.user_id=? AND msg.id>m.last_read AND msg.user_id<>?',[$tid,$u['id'],$u['id']]);if($count)$out[]=['id'=>'chat','version'=>(int)g('SELECT COALESCE(MAX(msg.id),0) FROM px_messages msg JOIN px_members m ON m.thread_id=msg.thread_id AND m.tenant_id=msg.tenant_id WHERE m.tenant_id=? AND m.user_id=? AND msg.id>m.last_read AND msg.user_id<>?',[$tid,$u['id'],$u['id']]),'text'=>$count.' unread school chat messages','url'=>'?s=chat','priority'=>'normal'];}if($u['role']==='parent'&&pp_ready()){foreach(pp_children($u) as $s){if(xp_has('op_notifications'))foreach(q('SELECT id,kind,body FROM op_notifications WHERE tenant_id=? AND student_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 3 DAY) ORDER BY id DESC LIMIT 3',[$tid,$s['id']]) as $r)$out[]=['id'=>'transport-'.$r['id'],'text'=>$s['name'].' · '.$r['kind'].': '.mb_substr($r['body'],0,160),'url'=>'?s=family&child='.$s['id'].'&view=transport','priority'=>'important'];foreach(q("SELECT id,kind,status,reply FROM pp_requests WHERE tenant_id=? AND user_id=? AND student_id=? AND (reply IS NOT NULL OR status IN ('approved','rejected')) ORDER BY id DESC LIMIT 3",[$tid,$u['id'],$s['id']]) as $r)$out[]=['id'=>'request-'.$r['id'].'-'.$r['status'],'text'=>$s['name'].' · '.$r['kind'].' request: '.$r['status'],'url'=>'?s=family&child='.$s['id'].'&view='.($r['kind']==='message'?'messages':$r['kind']),'priority'=>'normal'];}}if($u['role']==='teacher'&&pp_ready()){$n=(int)g("SELECT COUNT(*) FROM pp_bookings b JOIN pp_slots s ON s.id=b.slot_id AND s.tenant_id=b.tenant_id WHERE b.tenant_id=? AND s.teacher_user_id=? AND b.status='booked' AND s.starts_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 2 DAY)",[$tid,$u['id']]);if($n)$out[]=['id'=>'booking-'.$n,'text'=>$n.' parent appointments coming up','url'=>'?s=family','priority'=>'important'];}if($u['role']==='school_admin'&&pp_ready()){$n=(int)g("SELECT COUNT(*) FROM pp_requests WHERE tenant_id=? AND status='pending' AND kind IN ('absence','pickup')",[$tid]);if($n)$out[]=['id'=>'reviews-'.$n,'text'=>$n.' family absence / pickup requests await review','url'=>'?s=family','priority'=>'important'];}if(xp_has('eg_deliveries')&&xp_has('eg_campaigns'))foreach(q("SELECT c.id,c.title FROM eg_deliveries d JOIN eg_campaigns c ON c.id=d.campaign_id AND c.tenant_id=d.tenant_id WHERE d.tenant_id=? AND d.user_id=? AND d.channel='inapp' AND d.status='delivered' AND c.kind='emergency' AND d.updated_at>=DATE_SUB(NOW(),INTERVAL 3 DAY) ORDER BY c.id DESC LIMIT 3",[$tid,$u['id']])->fetchAll() as $r)$out[]=['id'=>'emergency-'.$r['id'],'text'=>'Important school notice: '.$r['title'],'url'=>'?s=announcements','priority'=>'important'];return array_slice($out,0,15);}
